import os, json, glob, math
import numpy as np

def _flatten_json(obj):
    stack = [((), obj)]
    paths = {}
    while stack:
        path, cur = stack.pop()
        if isinstance(cur, dict):
            for k, v in cur.items():
                stack.append((path + (k,), v))
        elif isinstance(cur, list):
            for i, v in enumerate(cur):
                stack.append((path + (i,), v))
        else:
            paths[path] = cur
    return paths

def _find_len32_arrays(obj):
    arrs = []
    # recursive search for any list/tuple of len 32 with all numeric
    def rec(x):
        if isinstance(x, (list, tuple)) and len(x) == 32 and all(isinstance(v, (int, float)) for v in x):
            arrs.append(np.array(x, dtype=float))
        elif isinstance(x, dict):
            for v in x.values():
                rec(v)
        elif isinstance(x, (list, tuple)):
            for v in x:
                rec(v)
    rec(obj)
    return arrs

def _choose_gamma_arrays(file_pat):
    out = []
    for p in sorted(glob.glob(file_pat)):
        try:
            with open(p, 'r') as f:
                data = json.load(f)
        except Exception as e:
            print(f"[warn] gamma load failed {p}: {e}")
            continue
        # prefer explicit keys
        cand = None
        for k in ['gamma', 'gamma_t', 'gamma_values', 'learnable_gamma', 'g_t']:
            if isinstance(data, dict) and k in data and isinstance(data[k], (list, tuple)) and len(data[k]) == 32:
                cand = np.array(data[k], dtype=float); break
        if cand is None:
            arrs = _find_len32_arrays(data)
            # gamma typically in [0,1], mean ~0.5–0.95
            filtered = [a for a in arrs if a.min() >= -0.1 and a.max() <= 1.5 and 0.2 <= float(np.mean(a)) <= 1.1]
            cand = filtered[0] if filtered else (arrs[0] if arrs else None)
        if cand is not None:
            out.append(cand)
        else:
            print(f"[warn] no gamma array found in {p}")
    return out

def _choose_mae_arrays(file_pat):
    out = []
    for p in sorted(glob.glob(file_pat)):
        try:
            with open(p, 'r') as f:
                data = json.load(f)
        except Exception as e:
            print(f"[warn] cond load failed {p}: {e}")
            continue
        # collect candidate arrays by key names that suggest MAE/errors
        candidates = []
        def rec(obj, key_path=()):
            if isinstance(obj, dict):
                for k, v in obj.items():
                    rec(v, key_path + (str(k),))
            elif isinstance(obj, list):
                if len(obj) == 32 and all(isinstance(v, (int, float)) for v in obj):
                    candidates.append(("/".join(key_path), np.array(obj, dtype=float)))
                else:
                    for i, v in enumerate(obj):
                        rec(v, key_path + (str(i),))
        rec(data)
        # filter by plausible MAE magnitude (ZAPBench step MAE ~0.02-0.04)
        plausible = [(kp, a) for kp, a in candidates if 0.01 <= float(np.mean(a)) <= 0.05 and a.max() < 0.2]
        if not plausible:
            # fallback: average across dict-of-conditions with plausible ranges
            arrs = [a for _, a in candidates]
            if arrs:
                stacked = np.stack(arrs, axis=0)
                avg = np.mean(stacked, axis=0)
                if 0.01 <= float(np.mean(avg)) <= 0.05 and avg.max() < 0.2:
                    out.append(avg); continue
            print(f"[warn] no plausible MAE arrays in {p}; skipping")
            continue
        # prefer keys containing 'mae' or 'error'
        mae_like = [(kp, a) for kp, a in plausible if any(s in kp.lower() for s in ['mae', 'error', 'abs'])]
        chosen = mae_like[0][1] if mae_like else plausible[0][1]
        out.append(chosen)
    return out

def test():
    os.makedirs("storage/ariadne/analyses", exist_ok=True)
    g_files = "storage/ariadne/analyses/fourier_learn_gamma_export_v2/*.json"
    c_files = "storage/ariadne/analyses/fourier_learn_gamma_per_condition/*.json"

    gammas = _choose_gamma_arrays(g_files)
    maes = _choose_mae_arrays(c_files)

    lines = []
    lines.append("# Corrected γ[t]–Difficulty Analysis (Ariadne II)")
    lines.append(f"gamma_files_parsed = {len(gammas)}")
    lines.append(f"per_condition_files_parsed = {len(maes)}")

    if gammas:
        g_mean = np.mean(np.stack(gammas, axis=0), axis=0)
        lines.append("gamma_mean[0:8] = " + ", ".join(f"{x:.3f}" for x in g_mean[:8]))
        lines.append("gamma_mean[-8:] = " + ", ".join(f"{x:.3f}" for x in g_mean[-8:]))
    else:
        g_mean = None
        lines.append("gamma_mean = N/A")

    if maes:
        m_mean = np.mean(np.stack(maes, axis=0), axis=0)
        lines.append("step_mae_mean[0:8] = " + ", ".join(f"{x:.5f}" for x in m_mean[:8]))
        lines.append("step_mae_mean[-8:] = " + ", ".join(f"{x:.5f}" for x in m_mean[-8:]))
        lines.append(f"step_mae_mean_avg = {float(np.mean(m_mean)):.5f}")
    else:
        m_mean = None
        lines.append("step_mae_mean = N/A")

    if g_mean is not None and m_mean is not None and len(g_mean) == 32 and len(m_mean) == 32:
        corr = float(np.corrcoef(g_mean, m_mean)[0,1])
        lines.append(f"corr(gamma_mean, step_mae_mean) = {corr:.4f}")
    else:
        lines.append("corr = N/A (insufficient data)")

    out_path = "storage/ariadne/analyses/ariadne2_cond_gamma_report_v2.md"
    with open(out_path, "w") as f:
        f.write("\n".join(lines) + "\n")
    print("\n".join(lines))
    print(f"[saved] {out_path}")
    return "ok"
